#!/usr/bin/env node
/**
 * Build the browser half of the plugin into the module-loader wrapper that
 * `@deepseek-ai/dsh-client-modules` serves as `/plugins/<id>/client.js`.
 *
 * The real source lives in `src/client`; the generated `lib/client.js` is
 * committed because the DSH runtime never runs this build. Every bare import
 * (`react`, `react/jsx-runtime`, DSH client seeds) stays external and is
 * resolved by the shell's static module table.
 */
import { build } from 'esbuild'
import { mkdir, readFile, writeFile } from 'node:fs/promises'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const pkg = JSON.parse(await readFile(join(root, 'package.json'), 'utf8'))

const result = await build({
  absWorkingDir: root,
  entryPoints: ['src/client/index.jsx'],
  bundle: true,
  write: false,
  format: 'cjs',
  platform: 'browser',
  target: ['es2022'],
  jsx: 'automatic',
  jsxImportSource: 'react',
  packages: 'external',
  legalComments: 'none',
  logLevel: 'info',
})

const output = result.outputFiles?.[0]
if (output === undefined) throw new Error('build-client: esbuild produced no JavaScript output')

const body = output.text.replace(/\n?\/\/# sourceMappingURL=[^\n]*\n?$/u, '\n')
const wrapped = `/* Generated by scripts/build-client.mjs from src/client; do not edit. */
window.__ModuleLoader__.load({
  id: ${JSON.stringify(pkg.name)},
  factory: (require) => {
    var module = { exports: {} };
    var exports = module.exports;
${body}
    return module.exports;
  }
});
`

await mkdir(join(root, 'lib'), { recursive: true })
await writeFile(join(root, 'lib', 'client.js'), wrapped)
console.log(`build-client: wrote lib/client.js (${Buffer.byteLength(wrapped)} bytes)`)
